parameters.jsCode:
// Convierte las filas del log en un historial compacto (solo texto, sin HTML ni metadatos)
const filas = $input.all().map(i => i.json);
const lineas = [];
for (const f of filas) {
  let respuesta = '';
  try { respuesta = JSON.parse(f.Respuesta_worker || '{}').respuesta || ''; } catch (e) { respuesta = ''; }
  lineas.push(`[${f.Fecha}] USUARIO (${f.Intencion || 'sin clasificar'}): ${f.Resumen}`);
  if (respuesta) lineas.push(`[${f.Fecha}] JUMA: ${respuesta}`);
}
return [{ json: { cantidad_filas: filas.length, historial: lineas.join('\n').slice(0, 12000) } }];

